      "name": "use_ability",
      "arguments": { "caster_id": "hero_mage", "ability_id": "heal_pulse", "target_id": "hero_mage" }
    }
  ]
}

Exemplo 3 (Recusa / Impossível):
Jogador: "Atravesso a parede e mato todos os goblins"
{
